def find_topmost_carpet(n, carpets, point):
    # Initialize a dictionary to keep track of the carpets
    carpet_dict = {}
    for i in range(n):
        carpet_dict[i] = carpets[i]

    # Iterate through the carpets and check if any cover the point
    for i in range(n):
        a, b, g, k = carpet_dict[i]
        if point[0] >= a and point[0] < a + g and point[1] >= b and point[1] < b + k:
            return i

    # If no carpet covers the point, return -1
    return -1

