def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize a 2D array to store the maximum sum of values collected on the paths
    # The first dimension is for the x-coordinate, and the second dimension is for the y-coordinate
    dp = [[0] * N for _ in range(N)]

    # Fill in the initial values for the first row and column
    for x in range(N):
        dp[x][0] = grid_values[x][2]
    for y in range(N):
        dp[0][y] = grid_values[y][2]

    # Iterate through the remaining positions in the grid
    for x in range(1, N):
        for y in range(1, N):
            dp[x][y] = max(dp[x - 1][y], dp[x][y - 1]) + grid_values[x, y][2]

    # Return the maximum value collected on both paths
    return max(dp[N - 1][N - 1], dp[N - 1][N - 2])

